window.RP_SESSION={"id":"S-ca5e7318ea15","messages":[{"id":"RP-III-0161140","time":"2026-08-28T23:45:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 돈으로 살 수 없는 것은 이 세상에 없다. 달리 말하자면 그 어떤 것이든 돈에 팔 수 있다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0161141","time":"2026-08-28T23:46:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 올리브가 돈을 버는 이유는, 행복한 삶을 위하여. 그걸 위해서 자신이 무엇까지 팔았고, 무엇은 차마 팔지 못했는가.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0161142","time":"2026-08-28T23:47:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그리고 그 아이는 뭘 위하여... .....","characters":["P-6ba6a097816f"]},{"id":"RP-III-0161143","time":"2026-08-28T23:48:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그럼에도 여전히, 나를 걱정해주는 사람이 있다는 것이 기뻤어. 정말 오랜만에 사람에 의해, 사람을 위해 심장이 뛰었던 것도.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0161144","time":"2026-08-28T23:50:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 내가 걱정할 것이 는다는 것의 기쁨과 두려움을 팔아버렸는데도, 다시 돌아와버렸다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0161145","time":"2026-08-28T23:50:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"이거 완전 이득이잖아! 신나라!","characters":["P-6ba6a097816f"]},{"id":"RP-III-0161146","time":"2026-08-28T23:51:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6ba6a097816f"]},{"id":"RP-III-0161147","time":"2026-08-28T23:51:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
